/* === Shared design system for Onyx Works === */
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
:root {
  --brand: #E6007E;
  --brand-dark: #c2006a;
  --brand-soft: #fde4f0;
  --ink: #111418;
  --ink-2: #2a2f37;
  --muted: #6a7280;
  --muted-2: #8a93a0;
  --line: #e6e8eb;
  --line-2: #eef0f3;
  --bg: #ffffff;
  --bg-soft: #f7f8fa;
  --bg-warm: #fafafb;
  --green: #0fa37f;
  --green-soft: #d8f1e8;
  --amber: #c98a00;
  --amber-soft: #fbeccd;
  --red: #c4314b;
  --red-soft: #fbe1e6;
  --blue: #2d6cdf;
  --blue-soft: #e1ebfa;
  --purple: #6c4ed0;
  --purple-soft: #ece5fb;
  --teal: #0aa4b0;
  --teal-soft: #d5f1f3;
  --radius: 8px;
  --radius-sm: 6px;
  --shadow: 0 1px 2px rgba(15, 18, 22, 0.04);
}
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  color: var(--ink);
  background: var(--bg);
  font-size: 13.5px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

/* === Layout shell === */
.shell { display: grid; grid-template-columns: 200px 1fr; min-height: 100vh; }

.sidebar {
  border-right: 1px solid var(--line);
  padding: 16px 14px 24px;
  background: #fff;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.brand {
  display: flex; align-items: center; gap: 8px;
  font-weight: 700; font-size: 13px;
  padding: 4px 6px;
}
.brand-mark {
  width: 18px; height: 18px;
  background: var(--ink);
  border-radius: 4px;
  display: inline-block;
  position: relative;
}
.brand-mark::after {
  content: "";
  position: absolute; inset: 4px;
  background: var(--brand);
  border-radius: 50%;
}
.nav-group { display: flex; flex-direction: column; gap: 2px; }
.nav-label {
  font-size: 10px; font-weight: 600;
  letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--muted-2);
  padding: 6px 8px 4px;
}
.nav a, .nav-item {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 8px; border-radius: 6px;
  font-size: 13px; color: var(--ink-2);
  text-decoration: none;
}
.nav a:hover { background: var(--bg-soft); }
.nav a.active, .nav-item.active {
  background: var(--brand); color: #fff;
}
.nav-icon {
  width: 14px; height: 14px; display: inline-block;
  border: 1.5px solid currentColor; border-radius: 3px; opacity: 0.85;
}
.nav-icon.dot { border-radius: 50%; }
.nav-icon.bar { border: 0; background: currentColor; height: 10px; }

.profile-card {
  margin-top: auto;
  display: flex; align-items: center; gap: 8px;
  padding: 8px; border-radius: 8px;
  background: var(--bg-soft);
}
.profile-card .avatar { width: 28px; height: 28px; font-size: 10px; }
.profile-card .name { font-size: 12px; font-weight: 600; line-height: 1.2; }
.profile-card .role { font-size: 11px; color: var(--muted); }

/* === Main area === */
.main { display: flex; flex-direction: column; min-width: 0; }
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 24px;
  border-bottom: 1px solid var(--line);
  gap: 12px;
  flex-wrap: wrap;
}
.crumbs { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); }
.crumbs .sep { color: var(--muted-2); }
.crumbs strong { color: var(--ink); font-weight: 600; }
.search {
  flex: 1; max-width: 360px;
  display: flex; align-items: center; gap: 6px;
  border: 1px solid var(--line); border-radius: 6px;
  padding: 6px 10px;
  background: #fff;
  color: var(--muted);
  font-size: 12px;
}
.search::before {
  content: ""; width: 12px; height: 12px;
  border: 1.5px solid var(--muted-2); border-radius: 50%;
}
.topbar-actions { display: flex; gap: 8px; align-items: center; }

/* === Buttons === */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 7px 12px;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  font-size: 12.5px; font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  line-height: 1.2;
}
.btn:hover { background: var(--bg-soft); }
.btn-primary { background: var(--brand); color: #fff; border-color: var(--brand); }
.btn-primary:hover { background: var(--brand-dark); }
.btn-ghost { border-color: transparent; background: transparent; }
.btn-sm { padding: 5px 9px; font-size: 11.5px; }
.btn-block { width: 100%; }
.btn-link { background: none; border: none; color: var(--brand); padding: 0; font-weight: 500; }

/* === Avatars === */
.avatar {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--bg-soft);
  color: var(--ink-2);
  font-weight: 600;
  font-size: 11px;
  display: inline-flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.avatar.pink { background: var(--brand-soft); color: var(--brand); }
.avatar.green { background: var(--green-soft); color: var(--green); }
.avatar.blue { background: var(--blue-soft); color: var(--blue); }
.avatar.amber { background: var(--amber-soft); color: var(--amber); }
.avatar.purple { background: var(--purple-soft); color: var(--purple); }
.avatar.teal { background: var(--teal-soft); color: var(--teal); }
.avatar.lg { width: 40px; height: 40px; font-size: 13px; }
.avatar.xl { width: 56px; height: 56px; font-size: 16px; }

/* === Page wrapper === */
.page {
  padding: 20px 24px 40px;
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 20px;
  align-items: start;
}
.page > .col-main { min-width: 0; display: flex; flex-direction: column; gap: 16px; }
.page > .col-side { display: flex; flex-direction: column; gap: 16px; }
.page-title {
  font-size: 24px; font-weight: 700; letter-spacing: -0.01em;
  margin: 4px 0 10px;
}
.page-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; flex-wrap: wrap;
}

/* === Cards === */
.card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
}
.card-pad { padding: 14px 16px; }
.card-head {
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  display: flex; align-items: center; justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}
.card-title { font-size: 14px; font-weight: 600; }
.card-sub { font-size: 11.5px; color: var(--muted); }
.card-body { padding: 12px 16px; }
.card-foot { padding: 10px 16px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; }

/* === KPI / stat tiles === */
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.kpi { padding: 12px 14px; border: 1px solid var(--line); border-radius: 8px; background: #fff; }
.kpi .label { font-size: 10.5px; font-weight: 600; color: var(--muted); letter-spacing: 0.06em; text-transform: uppercase; }
.kpi .val { font-size: 22px; font-weight: 700; margin-top: 2px; }
.kpi .sub { font-size: 11px; color: var(--muted); margin-top: 2px; }
.kpi .sub.pos { color: var(--green); }
.kpi .sub.neg { color: var(--red); }

/* === Badges === */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 11px; font-weight: 500;
  background: var(--bg-soft); color: var(--ink-2);
  border: 1px solid var(--line);
  white-space: nowrap;
}
.badge .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.badge.green { background: var(--green-soft); color: var(--green); border-color: transparent; }
.badge.amber { background: var(--amber-soft); color: var(--amber); border-color: transparent; }
.badge.red { background: var(--red-soft); color: var(--red); border-color: transparent; }
.badge.pink { background: var(--brand-soft); color: var(--brand); border-color: transparent; }
.badge.blue { background: var(--blue-soft); color: var(--blue); border-color: transparent; }
.badge.purple { background: var(--purple-soft); color: var(--purple); border-color: transparent; }
.badge.teal { background: var(--teal-soft); color: var(--teal); border-color: transparent; }
.badge.gray { background: var(--bg-soft); color: var(--muted); border-color: transparent; }

/* === Tables === */
.tbl { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.tbl thead th {
  text-align: left; font-weight: 600; font-size: 10.5px;
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--muted);
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--bg-warm);
}
.tbl tbody td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line-2);
  vertical-align: middle;
}
.tbl tbody tr:last-child td { border-bottom: 0; }
.tbl .num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl .nowrap { white-space: nowrap; }

/* === Tabs (horizontal pills) === */
.tabs {
  display: flex; flex-wrap: wrap; gap: 2px;
  border-bottom: 1px solid var(--line);
  padding: 0 4px;
}
.tab {
  padding: 8px 12px;
  font-size: 12.5px; font-weight: 500;
  color: var(--muted);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  cursor: pointer;
}
.tab.active { color: var(--ink); border-bottom-color: var(--ink); }
.tabs-inline { display: inline-flex; gap: 4px; flex-wrap: wrap; }
.tabs-inline .tab { padding: 5px 10px; border-radius: 6px; border-bottom: 0; background: transparent; }
.tabs-inline .tab.active { background: var(--brand); color: #fff; }

/* === Filter chips / inputs === */
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 10px;
  border-radius: 6px;
  border: 1px solid var(--line);
  background: #fff;
  font-size: 12px;
  color: var(--ink-2);
  white-space: nowrap;
}
.chip .caret::after {
  content: "";
  display: inline-block; width: 6px; height: 6px;
  border-right: 1.5px solid var(--muted); border-bottom: 1.5px solid var(--muted);
  transform: rotate(45deg); margin-left: 2px; margin-bottom: 2px;
}
.input, .select, textarea.input {
  width: 100%;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 12.5px;
  background: #fff;
  color: var(--ink);
  font-family: inherit;
}
textarea.input { resize: vertical; min-height: 80px; }
.field { display: flex; flex-direction: column; gap: 4px; }
.field-label { font-size: 11.5px; font-weight: 500; color: var(--ink-2); }
.fields-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.row-gap { display: flex; flex-direction: column; gap: 10px; }

/* === Calendar === */
.cal {
  width: 100%;
  display: grid; grid-template-columns: repeat(7, 1fr);
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
  background: #fff;
}
.cal .dow {
  text-align: left;
  font-size: 10px; font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.06em; text-transform: uppercase;
  padding: 6px 8px;
  background: var(--bg-warm);
  border-bottom: 1px solid var(--line);
}
.cal .day {
  min-height: 64px;
  padding: 4px 6px;
  border-right: 1px solid var(--line-2);
  border-bottom: 1px solid var(--line-2);
  font-size: 11px;
  display: flex; flex-direction: column; gap: 3px;
  background: #fff;
  position: relative;
}
.cal .day:nth-child(7n) { border-right: 0; }
.cal .day.mute { background: var(--bg-warm); color: var(--muted-2); }
.cal .day .d { font-size: 11px; font-weight: 600; color: var(--ink-2); }
.cal .day.today .d { color: #fff; background: var(--ink); width: 18px; height: 18px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; }
.cal .day.brand { background: var(--brand); color: #fff; }
.cal .day.brand .d { color: #fff; }
.cal .pill {
  font-size: 10px; padding: 1px 4px;
  border-radius: 3px;
  background: var(--green-soft); color: var(--green);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.cal .pill.amber { background: var(--amber-soft); color: var(--amber); }
.cal .pill.red { background: var(--red-soft); color: var(--red); }
.cal .pill.pink { background: var(--brand-soft); color: var(--brand); }
.cal .pill.gray { background: var(--bg-soft); color: var(--ink-2); }
.cal .pill.dark { background: var(--ink); color: #fff; }
.cal-legend {
  display: flex; flex-wrap: wrap; gap: 12px; padding: 8px 4px 0;
  font-size: 11px; color: var(--muted);
}
.cal-legend .key { display: inline-flex; align-items: center; gap: 5px; }
.cal-legend .sw { width: 10px; height: 10px; border-radius: 3px; background: var(--green-soft); }
.cal-legend .sw.amber { background: var(--amber-soft); }
.cal-legend .sw.pink { background: var(--brand); }
.cal-legend .sw.gray { background: var(--bg-soft); border: 1px solid var(--line); }

/* === Toolbar === */
.toolbar {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}
.spacer { flex: 1; }

/* === Sidebar (right-side) detail card === */
.detail .detail-row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 12.5px; border-bottom: 1px dashed var(--line-2); }
.detail .detail-row:last-child { border-bottom: 0; }
.detail .detail-row .k { color: var(--muted); }
.detail .detail-row .v { color: var(--ink); font-weight: 500; }

/* === Footer === */
.footer {
  padding: 14px 24px 22px;
  border-top: 1px solid var(--line);
  display: flex; justify-content: space-between; align-items: center;
  font-size: 11px; color: var(--muted);
  flex-wrap: wrap; gap: 6px;
}
.footer .links { display: flex; gap: 12px; }
.footer a { color: var(--muted); text-decoration: none; }

/* === Tree / org chart === */
.tree { display: flex; flex-direction: column; align-items: center; gap: 18px; }
.tree-row { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
.tree-node {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  min-width: 150px;
}
.tree-node.center { border-color: var(--brand); background: var(--brand); color: #fff; }
.tree-node.center .role { color: rgba(255,255,255,0.85); }
.tree-node .who { display: flex; flex-direction: column; }
.tree-node .nm { font-size: 12px; font-weight: 600; line-height: 1.2; }
.tree-node .role { font-size: 10.5px; color: var(--muted); }
.tree-connector {
  width: 2px; height: 16px; background: var(--line);
}

/* === Helpers === */
.row { display: flex; align-items: center; gap: 8px; }
.row.between { justify-content: space-between; }
.row.wrap { flex-wrap: wrap; }
.col { display: flex; flex-direction: column; gap: 8px; }
.mt-0 { margin-top: 0; } .mt-1 { margin-top: 4px; } .mt-2 { margin-top: 8px; } .mt-3 { margin-top: 12px; }
.mb-0 { margin-bottom: 0; } .mb-2 { margin-bottom: 8px; }
.small { font-size: 11px; color: var(--muted); }
.tiny { font-size: 10.5px; color: var(--muted); letter-spacing: 0.04em; }
.muted { color: var(--muted); }
.right { text-align: right; }
.bold { font-weight: 600; }
.divider { height: 1px; background: var(--line); }
.pill-tab {
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 12px;
  background: #fff;
}
.pill-tab.active { background: var(--ink); color: #fff; border-color: var(--ink); }

/* === Top header strip (above topbar on some pages) === */
.workspace-strip {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 24px;
  border-bottom: 1px solid var(--line);
  font-size: 11.5px;
  color: var(--muted);
  gap: 8px;
}
.workspace-strip .grp { display: flex; gap: 6px; align-items: center; }

/* === Mobile top nav === */
.mobile-top { display: none; }

/* === Responsive: tablet === */
@media (max-width: 1100px) {
  .shell { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .mobile-top {
    display: flex; align-items: center; justify-content: space-between;
    padding: 10px 16px;
    border-bottom: 1px solid var(--line);
    gap: 8px;
  }
  .mobile-top .brand { padding: 0; font-size: 13px; }
  .mobile-top .hnav { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; }
  .mobile-top .hnav a, .mobile-top .hnav .nav-item {
    padding: 5px 10px;
    border-radius: 6px;
    font-size: 12px; color: var(--ink-2);
    text-decoration: none;
  }
  .mobile-top .hnav .nav-item.active, .mobile-top .hnav a.active {
    background: var(--brand); color: #fff;
  }
  .second-strip {
    display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
    padding: 8px 16px;
    border-bottom: 1px solid var(--line);
    font-size: 12px;
  }
  .second-strip .sect-label {
    font-size: 10px; font-weight: 600; color: var(--muted-2);
    text-transform: uppercase; letter-spacing: 0.06em;
    padding-right: 6px;
  }
  .second-strip .links { display: flex; gap: 6px; flex-wrap: wrap; }
  .second-strip .links a {
    padding: 4px 8px; border-radius: 6px;
    color: var(--ink-2); text-decoration: none; font-size: 12px;
  }
  .second-strip .links a.active { background: var(--brand); color: #fff; }
  .page { grid-template-columns: 1fr; padding: 16px; }
  .topbar { padding: 10px 16px; }
  .kpis { grid-template-columns: repeat(2, 1fr); }
}

/* === Responsive: mobile === */
@media (max-width: 560px) {
  body { font-size: 13px; }
  .page { padding: 12px; gap: 12px; }
  .topbar { padding: 10px 12px; flex-direction: column; align-items: stretch; }
  .topbar .search { max-width: none; }
  .topbar-actions { justify-content: space-between; }
  .page-title { font-size: 20px; }
  .kpis { grid-template-columns: 1fr; }
  .cal .day { min-height: 48px; padding: 3px 4px; }
  .cal .day .d { font-size: 10px; }
  .cal .pill { font-size: 9px; }
  .fields-2 { grid-template-columns: 1fr; }
  .footer { padding: 14px 12px; }
  .card-pad, .card-body, .card-head, .card-foot { padding-left: 12px; padding-right: 12px; }
  .tbl thead th, .tbl tbody td { padding: 8px 10px; font-size: 11.5px; }
  .second-strip { padding: 8px 12px; }
  .mobile-top { padding: 10px 12px; }
}

